target.css:
:root {
  --ink: #20283b;
  --paper: #fffaf0;
  --paper-deep: #f2e7d3;
  --line: #d8c8ad;
  --navy: #263b5a;
  --navy-dark: #17243b;
  --orange: #e96d3f;
  --yellow: #f5c84b;
  --mint: #75c5aa;
  --muted: #728096;
  --white: #ffffff;
}

* { box-sizing: border-box; }

.console {
  width: 470px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.console-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 14px 9px;
}

.title-block { min-width: 0; }

.eyebrow {
  margin: 0 0 2px;
  color: var(--orange);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1px;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  color: var(--navy-dark);
  font-size: 21px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.6px;
}

.roll-badge {
  padding: 5px 8px;
  color: var(--navy-dark);
  background: var(--yellow);
  border-radius: 6px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.exposure-nav {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0 14px;
  overflow: hidden;
  background: var(--paper-deep);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 6px 10px;
  border-right: 1px solid var(--line);
}

.stat:last-child { border-right: 0; }

.stat span, .panel-label, figcaption {
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.65px;
  text-transform: uppercase;
}

.stat strong {
  color: var(--navy-dark);
  font-size: 12px;
  line-height: 1.15;
}

.workspace {
  display: grid;
  grid-template-columns: 112px 1fr;
  gap: 10px;
  padding: 10px 14px;
}

.recipe {
  padding: 9px;
  color: var(--paper);
  background: var(--navy);
  border-radius: 9px;
}

.panel-label { margin: 0; color: var(--mint); }

.frame-number {
  display: block;
  margin-top: 1px;
  color: var(--white);
  font-size: 32px;
  line-height: 0.9;
  letter-spacing: -1px;
}

.frame-note {
  display: block;
  margin-top: 4px;
  color: var(--paper-deep);
  font-size: 9px;
  font-weight: 600;
  line-height: 1.25;
}

hr {
  height: 1px;
  margin: 6px 0 5px;
  border: 0;
  background: var(--mint);
  opacity: 0.55;
}

.recipe-line {
  display: flex;
  justify-content: space-between;
  margin: 2px 0;
  color: var(--paper-deep);
  font-size: 9px;
}

.recipe-line b { color: var(--white); }

.sheet {
  min-width: 0;
  margin: 0;
  padding: 8px;
  background: var(--navy-dark);
  border-radius: 9px;
}

figcaption {
  display: flex;
  justify-content: space-between;
  margin-bottom: 5px;
  color: var(--mint);
  font-size: 7px;
}

.frames {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 4px;
}

.frame {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  aspect-ratio: 1.2;
  padding: 2px;
  color: var(--navy-dark);
  background: var(--mint);
  border: 2px solid var(--mint);
  border-radius: 3px;
  font-size: 7px;
  font-style: normal;
  font-weight: 800;
  line-height: 1;
}

.frame.pale {
  background: var(--paper-deep);
  border-color: var(--paper-deep);
}

.frame.warm {
  background: var(--orange);
  border-color: var(--orange);
}

.frame.selected {
  color: var(--paper);
  background: var(--navy-dark);
  border-color: var(--yellow);
}

.console-footer {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 14px;
  color: var(--navy);
  background: var(--paper-deep);
  border-top: 1px solid var(--line);
  font-size: 10px;
  font-weight: 700;
}

.ready-dot {
  color: var(--mint);
  font-size: 13px;
  line-height: 0;
}

button {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  padding: 6px 9px;
  color: var(--white);
  background: var(--orange);
  border: 0;
  border-radius: 6px;
  font: inherit;
  font-size: 10px;
  font-weight: 800;
}

button span {
  font-size: 13px;
  line-height: 0.7;
}

